namespace Jsonata.Net.Core.Parsing { public enum TokenType {     EOF, Unknown, Error,     StringLiteral, NumericLiteral, BooleanLiteral, NullLiteral,     Identifier, Variable,     Function, /* New token type for 'function' keyword */     DollarSign, /* New token type for '$' */     Dot, Comma, Colon, Semicolon,     LeftParen, RightParen, LeftBracket, RightBracket, LeftBrace, RightBrace,     Plus, Minus, Asterisk, Slash, Percent,     Equals, NotEquals, LessThan, LessThanOrEqual, GreaterThan, GreaterThanOrEqual,     And, Or, In,     Concatenate,     Assign, /* := */     Question /* ? */     /* Add more as parser develops: e.g., Lambda, At, Hash, etc. */ } }
